 window.kitchenDebug={getState:()=>({loaded,paused,lang,bookPage,itemCount:items.length,items:items.map(i=>({kind:i.kind,x:i.body.position.x,y:i.body.position.y,angle:i.body.angle,speed:i.body.speed})),view:{camX,camY,viewW,viewH,width,height}}),worldToScreen:toScreen,reset};
