function resize(){width=$('#stage').clientWidth;height=$('#stage').clientHeight;renderer.setSize(width,height);const aspect=width/height;if(aspect>W/H){viewW=W;viewH=W/aspect}else{viewH=H;viewW=H*aspect;}camX=clamp(camX,viewW/2,W-viewW/2);panTarget=clamp(panTarget,viewW/2,W-viewW/2);camY=H/2;updateCamera();$('#instruction').textContent=t(width<600?'mobileInstruction':'instruction');}
function updateCamera(){camera.left=camX-viewW/2;camera.right=camX+viewW/2;camera.top=camY-viewH/2;camera.bottom=camY+viewH/2;camera.updateProjectionMatrix()}
function toWorld(x,y){return{x:camera.left+x/width*viewW-root.position.x,y:camera.top+y/height*viewH-root.position.y}}
function toScreen(x,y){return{x:(x+root.position.x-camera.left)/viewW*width,y:(y+root.position.y-camera.top)/viewH*height}}
function hit(p){return [...items].reverse().find(i=>{const local=Vector.rotate(Vector.sub(p,i.body.position),-i.body.angle);return Math.abs(local.x)<i.w*.48&&Math.abs(local.y)<i.h*.48})||flames.find(f=>Math.hypot(p.x-f.x,p.y-f.y)<30)||(Math.hypot(p.x-384,p.y-735)<47?{kind:'oven',x:384,y:735}:null)}
function activate(item){if(item.kind==='book')return openBook();if(item.kind==='lamp'){lampOn=!lampOn;chime('mug',.025);return}if(item.kind==='candle'){item.on=!item.on;return}if(item.kind==='oven'){ovenOn=!ovenOn;return}if(!paused&&item.body){Body.applyForce(item.body,{x:item.body.position.x,y:item.body.position.y+item.h*.25},{x:.018,y:-.004});chime(item.kind,.04)}}
function pointerDown(e,p,forced){if(!loaded||$('#book-dialog').open||e.button>0)return;releaseDrag();$('#welcome').classList.add('faded');const target=forced||hit(p);const base={pointerId:e.pointerId,startX:e.clientX,startY:e.clientY,startPan:panTarget,moved:0,target};if(target?.body&&!paused){const delta=Vector.sub(p,target.body.position);const local=Vector.rotate(delta,-target.body.angle);const pin=Constraint.create({pointA:p,bodyB:target.body,pointB:local,length:0,stiffness:.12,damping:.15,angularStiffness:0});Composite.add(engine.world,pin);drag={...base,pin};renderer.domElement.style.cursor='grabbing';}else drag={...base,panning:!target};try{renderer.domElement.setPointerCapture(e.pointerId)}catch{}$('#tooltip').classList.remove('visible');}
function pointerMove(e){if(!loaded)return;mouse=toWorld(e.clientX,e.clientY);if(drag&&e.pointerId===drag.pointerId){drag.moved=Math.max(drag.moved,Math.hypot(e.clientX-drag.startX,e.clientY-drag.startY));if(drag.pin){const b=drag.target.body;const dx=mouse.x-b.position.x,dy=mouse.y-b.position.y;const l=Math.hypot(dx,dy),s=l>220?220/l:1;drag.pin.pointA={x:b.position.x+dx*s,y:b.position.y+dy*s};}else if(drag.panning){panTarget=clamp(drag.startPan-(e.clientX-drag.startX)/width*viewW,viewW/2,W-viewW/2);}return}hover=hit(mouse);renderer.domElement.style.cursor=hover?.body?'grab':hover?'pointer':viewW<W?'ew-resize':'default';const tip=$('#tooltip');if(hover&&e.pointerType!=='touch'&&!$('#book-dialog').open){tip.textContent=t(hover.kind);tip.style.left=`${clamp(e.clientX,110,width-110)}px`;tip.style.top=`${e.clientY}px`;tip.classList.add('visible')}else tip.classList.remove('visible');}
function pointerUp(e){if(!drag||e.pointerId!==drag.pointerId)return;const {target,moved}=drag;releaseDrag();if(target&&moved<7)activate(target)}
function releaseDrag(){if(drag?.pin&&engine)Composite.remove(engine.world,drag.pin);drag=null;if(renderer)renderer.domElement.style.cursor='default'}
function reset(){if(!loaded)return;releaseDrag();items.forEach(i=>{Body.setPosition(i.body,i.initial);Body.setAngle(i.body,i.initial.angle);Body.setVelocity(i.body,{x:0,y:0});Body.setAngularVelocity(i.body,0)});chains.forEach(c=>c.nodes.forEach((n,i)=>{Body.setPosition(n,c.initial[i]);Body.setVelocity(n,{x:0,y:0})}));lampOn=ovenOn=true;flames.forEach(f=>f.on=true);panTarget=W/2;clock=0;accumulator=0;$('#live').textContent=t('reset');}
function physicsStep(){for(const item of items){if(item.table){Body.applyForce(item.body,item.body.position,{x:0,y:-item.body.mass*engine.gravity.y*engine.gravity.scale});if(item.body.speed>18)Body.setVelocity(item.body,Vector.mult(item.body.velocity,18/item.body.speed));}if(item.kind==='heart'&&!drag)Body.applyForce(item.body,item.body.position,{x:Math.sin(clock*.5+item.initial.x)*.000002,y:0});}Engine.update(engine,1000/60);}
function updateVisuals(dt){
 camX+=(panTarget-camX)*Math.min(1,dt*9);if(!paused&&!reduced.matches&&width>800&&!drag){root.position.x+=(clamp((mouse.x-W/2)/W,-.5,.5)*-5-root.position.x)*.035;root.position.y+=(clamp((mouse.y-H/2)/H,-.5,.5)*-3-root.position.y)*.035;}updateCamera();
 for(const item of items){const {body,mesh,shadow,w,h}=item;mesh.position.x=body.position.x;mesh.position.y=body.position.y;mesh.rotation.z=body.angle;shadow.position.set(body.position.x+5,body.position.y+(item.table?h*.32:7),item.depth-.1);shadow.scale.set(item.table?1:.9,item.table?.32:1,1);shadow.rotation.z=body.angle;if(item.cord){const tip=Vector.add(body.position,Vector.rotate({x:0,y:-h*.43},body.angle));const a=item.cord.geometry.attributes.position;a.setXYZ(0,item.hang.x,item.hang.y,item.depth-.05);a.setXYZ(1,tip.x,tip.y,item.depth-.05);a.needsUpdate=true;}}
 chains.forEach(c=>{const a=c.line.geometry.attributes.position;c.nodes.forEach((n,i)=>a.setXYZ(i,n.position.x,n.position.y,4));a.needsUpdate=true});
 for(const flame of flames){const f=.86+Math.sin(clock*9.3+flame.x)*.07+Math.sin(clock*17.1)*.035;flame.g.material.uniforms.opacity.value=flame.on?.3*f:.02;flame.f.visible=flame.core.visible=flame.on;flame.f.scale.set(1+Math.sin(clock*13)*.12,f,1);flame.core.scale.y=f;}
 glows.forEach(g=>{if(g.kind==='oven'){g.mesh.material.uniforms.opacity.value=ovenOn?.24+Math.sin(clock*4.6)*.055:.035;}else{const lamp=items.find(i=>i.kind==='lamp');g.mesh.position.x=lamp.body.position.x;g.mesh.position.y=lamp.body.position.y+62;g.mesh.material.uniforms.opacity.value=lampOn?.18+Math.sin(clock*2)*.012:0;lamp.mesh.material.color.set(lampOn?0xe6d2b1:0x776754);}});
 const food=items.find(i=>i.kind==='quiche');for(const puff of steam){const phase=(puff.phase+clock*.11)%1;const x=food.body.position.x+puff.drift*65+Math.sin(phase*8+puff.phase*19)*17;const y=food.body.position.y-38-phase*160;const dx=x-mouse.x,dy=y-mouse.y,d=Math.hypot(dx,dy);if(d<95&&!paused){puff.sx+=dx*.002;puff.sy+=dy*.001;}puff.sx*=.98;puff.sy*=.98;puff.mesh.position.set(x+puff.sx,y+puff.sy,18);puff.mesh.scale.set(.45+phase*.8,.4+phase*1.3,1);puff.mesh.rotation.z=Math.sin(phase*5+puff.phase)*.4;puff.mesh.material.uniforms.opacity.value=Math.sin(phase*Math.PI)*.06;}
 const a=dust.mesh.geometry.attributes.position;dust.seeds.forEach((s,i)=>{a.setXYZ(i,(s.x+Math.sin(clock*.07+i)*18+W)%W,(s.y-clock*s.s*3%H+H)%H,13)});a.needsUpdate=true;
 hotspotButtons.forEach(({button,item})=>{const p=item.body?item.body.position:item;const s=toScreen(p.x,p.y);button.style.left=`${s.x}px`;button.style.top=`${s.y}px`;button.classList.toggle('hidden',s.x<15||s.x>width-15||s.y<80||s.y>height-75);});
}
function frame(now){frameHandle=requestAnimationFrame(frame);if(document.hidden)return;const dt=Math.min((now-lastTime)/1000,.05);lastTime=now;if(!paused&&!$('#book-dialog').open){clock+=dt;accumulator+=dt;let steps=0;while(accumulator>=1/60&&steps<3){physicsStep();accumulator-=1/60;steps++;}}else accumulator=0;updateVisuals(paused?0:dt);renderer.render(scene,camera);}
setLanguage('ru');
init().catch(error=>{console.error('Kitchen initialization failed',error);$('#loading').classList.add('done');const note=document.createElement('p');note.className='error-note';note.textContent=t('error');$('#stage').append(note);$('#canvas-host').style.display='none';});
